export function villageMap(id) {
    return villageMaps.find((map) => map.id === id) ?? villageMaps[0];
}
export function villageGatePosts(map) {
    return map.points
        .filter((p) => ['wetland', 'coast', 'snow'].includes(p.id))
        .flatMap((p) => [-1, 1].map((side) => ({
        x: p.x + side * (p.id === 'coast' ? 1.8 : 1.7),
        z: p.z,
        radius: 0.12,
    })));
}
export function villageShoreRocks(map) {
    if (map.id !== 'harbor')
        return [];
    return Array.from({ length: 11 }, (_, i) => ({
        x: 5.85,
        z: -11 + i * 2.5,
        radius: 0.45 + (i % 3) * 0.08,
    })).filter((p) => Math.abs(p.z - 5) >= 2 && Math.abs(p.z + 2.3) >= 1.9);
}
